promql_queries.error_rps:
sum by (service_name) (
  rate(
    traces_span_metrics_calls_total{
      span_kind="SPAN_KIND_SERVER",
      status_code="STATUS_CODE_ERROR"
    }[30s]
  )
)

promql_queries.error_rate:
(
  sum by (service_name) (
    rate(
      traces_span_metrics_calls_total{
        span_kind="SPAN_KIND_SERVER",
        status_code="STATUS_CODE_ERROR"
      }[30s]
    )
  )
)
/
clamp_min(
  sum by (service_name) (
    rate(
      traces_span_metrics_calls_total{
        span_kind="SPAN_KIND_SERVER"
      }[30s]
    )
  ),
  1e-9
)

promql_queries.latency_ms:
sum by (service_name) (
  rate(
    traces_span_metrics_duration_milliseconds_sum{
      span_kind="SPAN_KIND_SERVER",
      span_name!~".*EventStream.*"
    }[30s]
  )
)
/
sum by (service_name) (
  rate(
    traces_span_metrics_duration_milliseconds_count{
      span_kind="SPAN_KIND_SERVER",
      span_name!~".*EventStream.*"
    }[30s]
  )
)
